            $scope.openMapModal = function (lat, long) {
                var mapUrl = "https://maps.google.com/maps?q=" + lat + "," + long + "&hl=es;z=14&output=embed";
                $scope.trustedMapUrl = $sce.trustAsResourceUrl(mapUrl);
            };

            let map;
            let mapInitialized = false;
            let mapMarkers = [];

            // Custom Leaflet SVG Pin Generator
            function getColoredMarkerIcon(colorHex) {
                return L.divIcon({
                    className: 'custom-leaflet-pin',
                    html: `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" width="32" height="32" style="filter: drop-shadow(1px 2px 3px rgba(0,0,0,0.5));">
                               <path fill="${colorHex}" d="M12 2C8.13 2 5 5.13 5 9c0 5.25 7 13 7 13s7-7.75 7-13c0-3.87-3.13-7-7-7z"/>
                               <circle fill="#ffffff" cx="12" cy="9" r="2.8"/>
                           </svg>`,
                    iconSize: [32, 32],
                    iconAnchor: [16, 32],
                    popupAnchor: [0, -30]
                });
            }

            // Lead College = RED, Other Colleges = BLUE
            const redLeadIcon = getColoredMarkerIcon('#8E2121'); // Red Marker for IsLeadClg == 1
            const blueOtherIcon = getColoredMarkerIcon('#184B9D'); // Blue Marker for other colleges

            // Dynamic Map Function: only MP colleges, IsLeadClg = 1 (Red), Other (Blue)
            $scope.openModal = function () {
                document.getElementById('mapModal').style.display = 'block';

                if (!mapInitialized) {
                    map = L.map("map").setView([23.4733, 77.9479], 7);
                    L.tileLayer("https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png", {
                        maxZoom: 18,
                    }).addTo(map);

                    mapInitialized = true;
                }

                // Clear existing markers
                mapMarkers.forEach(marker => map.removeLayer(marker));
                mapMarkers = [];

                const bounds = [];

                // Read dynamically from currently loaded/filtered $scope.College_Details
                $scope.College_Details_all.forEach(college => {
                    if (!college.cm_latitude || !college.cm_longitude) return;

                    let lat = parseFloat(college.cm_latitude);
                    let lng = parseFloat(college.cm_longitude);

                    // Auto-fix if latitude and longitude were accidentally swapped in DB
                    if (lat >= 74.0 && lat <= 83.0 && lng >= 21.0 && lng <= 27.2) {
                        let temp = lat;
                        lat = lng;
                        lng = temp;
                    }

                    // Strict filter: Only Madhya Pradesh geographic boundary (Lat: 21.0-27.2, Long: 74.0-83.0)
                    if (!isNaN(lat) && !isNaN(lng) && lat >= 21.0 && lat <= 27.2 && lng >= 74.0 && lng <= 83.0){

                        // Condition: IsLeadClg == 1 -> RED, otherwise -> BLUE
                        let markerIcon = (college.IsLeadClg == 1 || college.IsLeadClg == '1' || college.IsLeadClg === true)
                            ? redLeadIcon
                            : blueOtherIcon;

                        const marker = L.marker([lat, lng], { icon: markerIcon }).addTo(map);

                        // Dynamic popup with college name & details
                        let popupHtml = `
                            <div style="font-size: 13px; min-width: 170px;">
                                <strong style="color: #8E2121; font-size: 14px;">${college.College_Name}</strong><br/>
                                <span style="color: #333;"><b>Type:</b> ${college.College_Type || ''}</span><br/>
                                <span style="color: #666; font-size: 12px;">${college.cm_FullAddress || ''}</span>
                            </div>
                        `;
                        marker.bindPopup(popupHtml);

                        mapMarkers.push(marker);
                        bounds.push([lat, lng]);
                    }
                });

                if (bounds.length > 0) {
                    map.fitBounds(bounds, { padding: [25, 25] });
                }

                setTimeout(() => {
                    map.invalidateSize();
                }, 200);
            };

            $scope.closeModal = function () {
                document.getElementById('mapModal').style.display = 'none';
                mapMarkers.forEach(marker => map.removeLayer(marker));
                mapMarkers = [];
            };

            // Function To Load First 50 Then Scroll And Next 50 Data
            $scope.NextData = function () {
                let datafordisplay;

                if ($scope.College_Details_all_filtered && $scope.College_Details_all_filtered.length > 0) {
                    datafordisplay = $scope.College_Details_all_filtered;
                } else {
                    datafordisplay = $scope.College_Details_all;
                }

                if (datafordisplay) {
                    if ($scope.visibleCollegeCount < datafordisplay.length) {
                        let nextBatch = datafordisplay.slice(
                            $scope.visibleCollegeCount,
                            $scope.visibleCollegeCount + 50
                        );
                        $scope.College_Details = angular.copy($scope.College_Details.concat(nextBatch));
                        $scope.visibleCollegeCount += 50;
                    }
                }
            };

            var searchTimeout;

            // Search Colleges
            $scope.Search_College = function (event, searchText) {
                if (searchTimeout) {
                    $timeout.cancel(searchTimeout);
                }

                searchTimeout = $timeout(function () {
                    $scope.College_Details_all_filtered = angular.copy(applyFilters($scope.College_Details_all, $scope.filters));

                    if (searchText && searchText.trim() !== "") {
                        $scope.College_Details_all_filtered = $scope.College_Details_all_filtered.filter(function (item) {
                            return item.College_Name.toLowerCase().includes(searchText.toLowerCase());
                        });
                    }

                    $scope.College_Details = $scope.College_Details_all_filtered.slice(0, 50);
                    $scope.visibleCollegeCount = 50;
                    document.getElementById("Total_Counts").innerText = $scope.College_Details_all_filtered.length;
                }, 500);
            };

            $scope.preventEnter = function (event) {
                if (event.key === 'Enter') {
                    event.preventDefault();
                }
            };

            // Course Filter
            $scope.Course_Filter = (id) => {
                document.getElementById("preloader").style.display = "block";

                let selectedIDs = [];
                for (let id in $scope.CourseSelection) {
                    if ($scope.CourseSelection[id]) {
                        selectedIDs.push(id);
                    }
                }

                $scope.filters.Course_id = selectedIDs.toString();
                $scope.College_Details_all_filtered = angular.copy(applyFilters($scope.College_Details_all, $scope.filters));
                $scope.College_Details = $scope.College_Details_all_filtered.slice(0, 50);
                $scope.visibleCollegeCount = 50;

                var dummyEvent = null;
                var currentSearchText = $scope.searchText || "";
                $scope.Search_College(dummyEvent, currentSearchText);

                document.getElementById("Total_Counts").innerText = $scope.College_Details_all_filtered.length;

                setTimeout(() => {
                    document.getElementById("preloader").style.display = "none";
