            };

            document.querySelectorAll('.college-list').forEach((targetNode) => {
                const observer = new MutationObserver(function (mutationsList, observer) {
                    setTimeout(() => {
                        $scope.$apply(function () {
                            $scope.Data_Changes();
                        });
