            $scope.Data_Changes = function () {
                $scope.dgreIds = $scope.Course_Binds.map(item => item.dgre_id);
                $scope.DistIds = $scope.District_Bind.map(item => item.dist_id);
                $scope.CollegeTypetIds = $scope.universities.map(item => item.ebd_value);
                $scope.DegTypetIds = $scope.collage_type.map(item => item.ebd_value);
