                $scope.MinorityIds = [1, 2];

                const dgreCountMap = {};
                const distCountMap = {};
                const CollegeTypeMap = {};
                const DegTypeMap = {};
                const GenderMap = {};
                const NaacMap = {};
                const HostelTypeMap = {};
                const AutonomousMap = {};
                const MinorityMap = {};

                const colleges = ($scope.College_Details_all_filtered && $scope.College_Details_all_filtered.length > 0)
                    ? $scope.College_Details_all_filtered
                    : $scope.College_Details_all;

                if (!colleges) return;

                // Course Count
                colleges.forEach(({ Course_id }) => {
                    if (Course_id) {
                        const courseIds = Course_id.split('/');
                        $scope.dgreIds.forEach(id => {
                            if (courseIds.includes(String(id))) {
                                dgreCountMap[id] = (dgreCountMap[id] || 0) + 1;
                            }
                        });
                    }
                });
                $scope.dgreIdCounts = dgreCountMap;

                // District Count
                colleges.forEach(({ cm_dist_id }) => {
                    $scope.DistIds.forEach(id => {
                        if (cm_dist_id == id) {
                            distCountMap[id] = (distCountMap[id] || 0) + 1;
                        }
                    });
                });
                $scope.distIdCounts = distCountMap;

                // College Type Count
                colleges.forEach(({ cm_org_Type }) => {
                    $scope.CollegeTypetIds.forEach(id => {
                        if (cm_org_Type == id) {
                            CollegeTypeMap[id] = (CollegeTypeMap[id] || 0) + 1;
                        }
                    });
                });
                $scope.CollTypeIdCounts = CollegeTypeMap;

                // Degree Type Count
                colleges.forEach(({ cm_Course_Type }) => {
                    if (cm_Course_Type) {
                        const degTypeIds = cm_Course_Type.split(',');
                        $scope.DegTypetIds.forEach(id => {
                            if (degTypeIds.includes(String(id))) {
                                DegTypeMap[id] = (DegTypeMap[id] || 0) + 1;
                            }
                        });
                    }
                });
                $scope.DegTypeCounts = DegTypeMap;

                // Gender Type Count
                colleges.forEach(({ cm_gen_Type }) => {
                    $scope.GendertIds.forEach(id => {
                        if (cm_gen_Type == id) {
                            GenderMap[id] = (GenderMap[id] || 0) + 1;
                        }
                    });
                });
                $scope.GenTypeIdCounts = GenderMap;

                // Naac Grade Count
                colleges.forEach(({ cm_Naac_Grade }) => {
                    $scope.NaacGradeIds.forEach(id => {
                        if (cm_Naac_Grade == id) {
                            NaacMap[id] = (NaacMap[id] || 0) + 1;
                        }
                    });
                });
                $scope.NaacIdCounts = NaacMap;

                // Hostel Type Count
                colleges.forEach(({ chd_type_ids }) => {
                    if (typeof chd_type_ids === 'string' && chd_type_ids.trim() !== '') {
                        const degTypeIds = chd_type_ids.split(',').map(id => id.trim());
                        $scope.HostelTypeIds.forEach(id => {
                            if (degTypeIds.includes(String(id))) {
                                HostelTypeMap[id] = (HostelTypeMap[id] || 0) + 1;
                            }
                        });
                    }
                });
                $scope.HostelTypeCounts = HostelTypeMap;

                // College Autonomous Count
                colleges.forEach(({ cm_aut_status }) => {
                    $scope.AutonomousIds.forEach(id => {
                        if (cm_aut_status == id) {
                            AutonomousMap[id] = (AutonomousMap[id] || 0) + 1;
                        }
                    });
                });
                $scope.AutonomousCounts = AutonomousMap;

                // College Minority Count
                colleges.forEach(({ cm_MinorityStatus }) => {
                    $scope.MinorityIds.forEach(id => {
                        if (cm_MinorityStatus == id) {
                            MinorityMap[id] = (MinorityMap[id] || 0) + 1;
                        }
                    });
                });
                $scope.MinorityCounts = MinorityMap;
            };

